// usage: node scripts/films.ts -> src/films.gen.ts (one composition per src/features/<id>/Film.tsx)
import { existsSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import { root } from "./lib/feature.ts";

export function writeFilms() {
  const dir = join(root, "src/features");
  const ids = existsSync(dir)
    ? readdirSync(dir).filter((id) => !id.startsWith("_") && existsSync(join(dir, id, "Film.tsx"))).sort()
    : [];
  const lines = [
    "// generated by scripts/films.ts; don't edit",
    'import type { FilmDef } from "./kit/Film.tsx";',
    ...ids.map((id, i) => `import { film as f${i} } from "./features/${id}/Film.tsx";`),
    "",
    `export const films: FilmDef[] = [${ids.map((_, i) => `f${i}`).join(", ")}];`,
    "",
  ];
  writeFileSync(join(root, "src/films.gen.ts"), lines.join("\n"));
  return ids;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) console.log(`films: ${writeFilms().join(", ") || "(none)"}`);
